# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">OSMANLI DEVLETİ\'NİN KURULUŞUNA DAİR TARİHÇİLİK TEZLERİ (TAR.10.2.1)</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#1e40af">PAUL WITTEK (GAZA TEZİ)</text>\n  <text x="32" y="88" font-size="10.6" fill="#1e3a8a">• Osmanlı Beyliği\'nin kuruluş ve</text>\n  <text x="40" y="104" font-size="10.4" fill="#1e3a8a">yükselişindeki temel itici güç</text>\n  <text x="40" y="120" font-size="10.6" font-weight="bold" fill="#1e3a8a">"Gaza (Cihat) İdeolojisi"dir.</text>\n  <text x="32" y="144" font-size="10.6" fill="#1e3a8a">• Uç bölgesindeki gazilerin</text>\n  <text x="40" y="160" font-size="10.4" fill="#1e3a8a">Bizans\'a (Dârülharp) karşı</text>\n  <text x="40" y="176" font-size="10.4" fill="#1e3a8a">kutsal mücadelesi (1337 Bursa</text>\n  <text x="40" y="192" font-size="10.4" fill="#1e3a8a">Şehâdet Camii kitabesi kanıtı).</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#166534">M. FUAT KÖPRÜLÜ (SENTEZ TEZİ)</text>\n  <text x="257" y="88" font-size="10.6" fill="#14532d">• Kuruluş tek bir etkenle değil,</text>\n  <text x="265" y="104" font-size="10.6" font-weight="bold" fill="#14532d">çok yönlü siyasi-sosyal</text>\n  <text x="265" y="120" font-size="10.6" font-weight="bold" fill="#14532d">etkenlerle açıklanmalıdır:</text>\n  <text x="257" y="142" font-size="10.4" fill="#14532d">• Oğuz/Türkmen nüfus göçü,</text>\n  <text x="257" y="158" font-size="10.4" fill="#14532d">• Selçuklu devlet mirası,</text>\n  <text x="257" y="174" font-size="10.4" fill="#14532d">• Dört zümre: Gaziyân-ı Rûm,</text>\n  <text x="265" y="190" font-size="10.4" fill="#14532d">Ahîyân-ı Rûm, Bacıyân-ı Rûm,</text>\n  <text x="265" y="205" font-size="10.4" fill="#14532d">Abdalân-ı Rûm dayanışması.</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#92400e">HALİL İNALCIK (KOYUNHİSAR 1302)</text>\n  <text x="482" y="88" font-size="10.6" fill="#78350f">• Gaza ruhu + Moğol baskısıyla</text>\n  <text x="490" y="104" font-size="10.4" fill="#78350f">uçlara yığılan nüfus dinamizmi.</text>\n  <text x="482" y="126" font-size="10.6" font-weight="bold" fill="#78350f">• Gerçek kuruluş: 27 Temmuz</text>\n  <text x="490" y="142" font-size="10.6" font-weight="bold" fill="#78350f">1302 Koyunhisar (Bapheus)</text>\n  <text x="490" y="158" font-size="10.4" fill="#78350f">Zaferi (hanedan karizması).</text>\n  <text x="482" y="180" font-size="10.6" fill="#78350f">• İskân ve İstimalet (gönül alma,</text>\n  <text x="490" y="196" font-size="10.4" fill="#78350f">hoşgörü ve vergi adaleti) siyaseti.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Farklı tarihçilik görüşleri, Osmanlı\'nın kuruluşunu tek boyutlu değil çok boyutlu kanıtlarla anlamamızı sağlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KURULUŞ DÖNEMİ TEMEL SİYASİ VE ASKERÎ GELİŞMELERİ (1299-1353)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">OSMAN GAZİ DÖNEMİ (1281-1324/1326)</text>\n  <text x="35" y="88" font-size="10.8" fill="#581c87">• Söğüt (kışlak) ve Domaniç (yaylak) merkezli</text>\n  <text x="45" y="104" font-size="10.5" fill="#581c87">uç beyliği; Karacahisar, Bilecik ve İnegöl\'ün fethi.</text>\n  <text x="35" y="128" font-size="10.8" font-weight="bold" fill="#581c87">• 1302 Koyunhisar (Bapheus) Savaşı:</text>\n  <text x="45" y="144" font-size="10.5" fill="#581c87">Bizans ordusuna karşı kazanılan ilk büyük zafer;</text>\n  <text x="45" y="160" font-size="10.5" fill="#581c87">Osman Gazi\'nin uçlarda karizmatik lider olması.</text>\n  <text x="35" y="184" font-size="10.8" fill="#581c87">• Bursa\'nın ablukaya alınması ve ilk Osmanlı parası.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">ORHAN GAZİ DÖNEMİ (1326-1362)</text>\n  <text x="370" y="88" font-size="10.8" fill="#064e3b">• 1326 Bursa\'nın Fethi ⟶ Başkent yapıldı.</text>\n  <text x="370" y="110" font-size="10.8" font-weight="bold" fill="#064e3b">• 1329 Maltepe (Pelekanon) Savaşı:</text>\n  <text x="380" y="126" font-size="10.5" fill="#064e3b">Bizans İmparatoru III. Andronikos mağlup edildi.</text>\n  <text x="370" y="148" font-size="10.8" fill="#064e3b">• 1331 İznik ve 1337 İzmit\'in fethi.</text>\n  <text x="370" y="170" font-size="10.8" font-weight="bold" fill="#064e3b">• 1345 Karesioğulları Beyliği\'nin Alınması:</text>\n  <text x="380" y="186" font-size="10.5" fill="#064e3b">ATSB ilk adım + Donanma + 1353 Çimpe Kalesi.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Karesioğulları\'nın katılmasıyla Hacı İlbeyi, Evrenos Bey ve Ece Halil gibi tecrübeli komutanlar Osmanlı hizmetine girdi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BEYLİKTEN DEVLETE GEÇİŞİ VE HIZLI BÜYÜMEYİ SAĞLAYAN ETKENLER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">JEOPOLİTİK VE SİYASİ ETKENLER</text>\n  <text x="35" y="88" font-size="10.8" fill="#7c2d12">• 1. Uç Beyliği Konumu: Bizans sınırında kurulması,</text>\n  <text x="45" y="104" font-size="10.5" fill="#7c2d12">ticaret yollarına yakınlığı ve gaza yönünde büyüme.</text>\n  <text x="35" y="126" font-size="10.8" fill="#7c2d12">• 2. Beyliklerle Barışçıl İlişki: İlk yıllarda Anadolu</text>\n  <text x="45" y="142" font-size="10.5" fill="#7c2d12">Türk beylikleriyle çatışmadan kaçınması.</text>\n  <text x="35" y="164" font-size="10.8" fill="#7c2d12">• 3. Bizans ve Balkanlar\'ın Durumu: Bizans\'ta taht</text>\n  <text x="45" y="180" font-size="10.5" fill="#7c2d12">kavgaları ve tekfurların halka ağır vergi baskısı.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">SOSYAL VE KURUMSAL ETKENLER</text>\n  <text x="370" y="88" font-size="10.8" fill="#1e3a8a">• 4. İskân ve İstimalet Siyaseti: Fethedilen yerlere</text>\n  <text x="380" y="104" font-size="10.5" fill="#1e3a8a">Türkmen iskânı; gayrimüslim halka hoşgörü ve adalet.</text>\n  <text x="370" y="126" font-size="10.8" fill="#1e3a8a">• 5. Ahîler ve Dervişler: Şeyh Edebali ve Ahî teşkilatı</text>\n  <text x="380" y="142" font-size="10.5" fill="#1e3a8a">ile Horasan erenlerinin (Abdalân-ı Rûm) desteği.</text>\n  <text x="370" y="164" font-size="10.8" fill="#1e3a8a">• 6. Teşkilatlanma: İlk düzenli ordu (Yaya-Müsellem),</text>\n  <text x="380" y="180" font-size="10.5" fill="#1e3a8a">Divan-ı Hümayun, İznik Medresesi (Davûd-ı Kayserî).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İstimalet ("gönül alma / uzlaştırıcı adalet") politikası, Balkan ve Anadolu halkının Osmanlı yönetimini benimsemesini sağlamıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
